      "summary": "배우 윤미라가 74세에도 수영복을 불사한 유튜브 도전기를 공개했다. 29일 방송된 MBC '라디오스타에서는 윤미라, 강남, 한다감, 박지현이 출연했다. 최근 유튜브 채널을 개설한 윤미라는 첫 영상부터 약 200만 조회수를 기록한 기적 같은 순간을 회상했다. 윤미라는 \"유튜브를 하게 됐는데 첫 영상이 200만 조회수가 나왔다. 다 놀랐다. 경이적이었다\"라고 밝혔다. 이어 \"구독자들을 실망시켜드리지 않게끔 유익한 콘텐츠를 보여드려야겠다, 있는 거 다 보여드려야겠다고 결심했다\"며 \"그래서 수영복까지 입었다\"고 말해 모두를 놀라게 했다. 그러나 윤미라는 유튜브 시작 초반에는 폭발적인 반응에 밤새 댓글을 읽었지만, 시간이 지나며 조회수가 점점 내려가 요즘 고민이 많다고 밝힌다. 이를 들은 강남은 \"사실 누나가 소개팅을 하면 대박난다\"며 윤미라의 유튜브 조회수를 위해 직접 콘텐츠 아이디어를 내 눈길을 끌었다.",
