      "summary": "미국 민주당의 차기 대권주자로 꼽히는 개빈 뉴섬 캘리포니아 주지사의 20년 전 불륜이 다시 수면 위로 떠올랐다. 당시 뉴섬의 부하 직원이자 측근의 아내였던 여성이 처음으로 관계의 전말을 공개하면서다. 28일(현지시간) 미국 잡지 배니티 페어 등에 따르면 루비 리피(54)는 최근 기고문을 통해 2005년 뉴섬 당시 샌프란시스코 시장과 수개월간 부적절한 관계를 맺었다고 밝혔다. 당시 뉴섬은 전 부인 킴벌리 길포일과 이혼 절차를 밟고 있었다. 반면 리피는 뉴섬의 친구이자 부비서실장이었던 알렉스 투르크와 결혼한 상태였다. 리피 역시 뉴섬의 부하 직원으로 샌프란시스코시에서 근무했다. 리피는 두 사람의 관계가 2005년 여름 시작돼 수개월 동안 만남과 헤어짐을 반복했다고 밝혔다. 뉴섬의 자택과 샌프란시스코의 술집, 로스앤젤레스의 한 호텔 등에서 만났다는 구체적인 설명도 내놨다. 그는 관계가 강요에 의한 것은 아니었으며 자신도 책임이 있다고 인정했다. 다만 직장 상사이자 시장이었던 뉴섬과의 권력",
