      "summary": "입대 전 남긴 가장 강렬한 흔적…팬들에게도 꽁꽁 숨겨 '동궁' 지난 17일 공개…세자 役으로 열연 호평 배우 곽동연은 늘 안정적인 연기를 보여주는 배우였다. 하지만 넷플릭스 시리즈 '동궁'에서는 조금 달랐다. 얼굴조차 제대로 드러나지 않는 연못 귀신부터 왕위를 향한 집착에 사로잡힌 비극의 세자까지 극의 반전을 책임지는 인물을 맡아 지금껏 보여주지 않았던 얼굴을 꺼내 들었다. 특수분장과 와이어, 대규모 CG가 더해진 새로운 도전이었다. 곽동연은 최근 서울 강남구의 한 카페에서 <더팩트>와 만나 넷플릭스 오리지널 시리즈 '동궁'(극본 권소라·서재원, 연출 최정규) 공개 기념 인터뷰를 진행했다. 극 중 미스터리의 중심에 선 인물 세자 역을 맡은 그는 작품과 캐릭터에 관한 다양한 이야기를 전했다. 지난 17일 8부작 전편 공개된 '동궁'은 구천(남주혁 분)과 귀신의 소리를 듣는 궁녀 생강(노윤서 분)이 왕(조승우 분)의 명을 받고 동궁에 얽힌 저주를 파헤치는 궁중 오컬트 미스터리다. 곽동연",
