      "summary": "'나는 솔로' 32기에서 순자가 영수의 차에 탔다가 담배 냄새에 질색했다. 29일 방송된 ENA·SBS Plus의 리얼 데이팅 프로그램 '나는 SOLO' 32기에서는 말 한마디로 위기를 맞은 영식과 뒤늦게 직진에 나선 영호, 순자의 직격탄에 흔들린 영수의 모습이 펼쳐졌다. 이날 방송에서는 첫 단추부터 살짝 엇갈렸던 순자와 영수의 데이트가 이어졌다. 데이트 장소로 향하기 위해 영수는 매너 있게 차문을 열어준 뒤 순자를 태웠다. 그러나 차에 타자마자 순자는 \"담배 냄새\"라며 인상을 썼다. 그러자 영수는 \"담배 냄새가 날 정도냐\"며 의아해했다. 스튜디오에서 이를 지켜보던 MC들도 지적을 이어갔다. \"차에서 담배를 피우면 안 좋은데\", \"차에서는 일반 담배를 피면 안 된다\"며 우려를 표했다. 특히 송해나는 \"(담배 냄새가 나면) 그걸 떠나서 이성적으로 매력이 확 떨어진다\"며 지적했다. 차에 탑승한 두 사람은 숙소에서 가까운 카페에 도착한 뒤 데이트를 이어갔다. 사진=ENA, SBS Plus",
