      "summary": "‘유 퀴즈 온 더 블럭’ 전 축구선수 박지성이 한국 축구와 일본의 차이점을 언급했다. 29일 방송된 tvN ‘유 퀴즈 온 더 블럭’에는 축구혁신위원장으로 활동 중인 박지성이 출연해 한국 축구를 둘러싼 생각을 밝혔다. 이날 박지성은 이전 월드컵과 이번 월드컵의 차이에 대해 “준비 과정이었다”고 말했다. 2026년 북중미 월드컵에 대한 아쉬움을 얘기한 그는 “카타르 월드컵에는 벤투 감독을 선임하고 월드컵까지 쭉 감독에 대해 믿음을 갖고 기다려주었다\"라고 운을 뗐다. 이어 “확실한 자기 색깔을 가지고 결과로 증명해냈기에 찬사를 받을 수 있었던 건데, 이번 월드컵 같은 경우는 그 과정 자체가 순탄치 않았다”고 설명했다. 감독 선임 과정을 언급하며 “가장 문제가 된 게 감독 선임 과정에서 협회가 공정하다는 느낌을 받지 못하게 선임 과정을 보여줬고, 그런 과정에서 여러 시끄러운 이야기들이 나오다 보니 안 팀이 신뢰받지 못한 상황에서 안 좋은 결과가 나오게 된 게 아닌가”라고 밝혔다. 한국과 일",
