      "summary": "\"내가 어떻게 서울에 올라왔는데…. 제가 자주 하는 말이에요. 여태까지 그렇게 끈을 놓지 않고 버텨서 여기까지 올 수 있었던 것 같아요.\" 배우 음문석이 데뷔 후 지나온 시간을 돌아보며 이같이 말했다. 2005년 가수로 데뷔한 그는 춤, 노래는 물론 영화 연출까지 도전하며 폭넓게 활동했다. 그런 그가 최근 영화 '호프'(감독 나홍진)를 통해 관객에게 강한 인상을 남겼다. '호프'는 배우로서 그의 존재감을 한 번 더 각인시킨 작품이 됐다. '호프'는 가상의 마을 호포항에 외계인이 출현하면서 벌어지는 이야기를 그린다. 외계인의 등장으로 위기에 놓인 사람들은 그 존재에 맞서기 시작한다. 음문석은 기괴한 분위기를 풍기는 호포항의 청년 양배 역을 맡았다. 음문석은 양배에 대해 \"여태 촬영한 작품 중에 제일 고민한 캐릭터\"라고 말했다. 나홍진 감독은 양배 역할에 대해 \"착하지도 않고 나쁘지도 않지만, 악 중의 악\"이라고 설명했다. 음문석은 캐릭터를 어떻게 표현할지 고민하던 중 3살 조카를 통해",
