      "summary": "영화 '호프'(HOPE)로 관객들의 눈도장을 찍은 음문석이 스크린 주연작 촬영을 이미 마친 것으로 알려졌다. 29일 오후 서울 삼청동에서 영화 '호프' 개봉 기념 인터뷰를 가진 음문석은 \"이번 영화에서 조연이지만 주연 못지않은 존재감을 보여줬다\"는 호평에 \"사실, 얼마 전에 주연으로 나오는 영화 촬영을 마쳤다. 내년 초쯤 선보일 수 있을 것 같다\"는 근황을 전했다. 그가 말한 영화는 '칸타르'다. 2022년 카자흐스탄 알마티에서 실제 일어난 사건에 픽션을 더한 추격 액션 영화다. 2020년 영화 '쓰리: 아직 끝나지 않았다'로 부산국제영화제 뉴커런츠상을 받으며 주목받았던 박루슬란 감독이 메가폰을 잡았고, 영화 '30일'을 만들었던 영화사 울림이 제작을 맡은 작품이다. 음문석은 \"카자흐스탄 올로케이션으로 4개월간 촬영을 하고 왔다. 사랑하는 사람을 구하러 가는 이야기다. 내년 초쯤 개봉할 것 같다. 기대해 달라\"고 신작에 대해 귀띔했다. 2005년 가수로 연예계에 데뷔해 댄서, TV",
