      "summary": "배우 황정민을 둘러싼 사생활 의혹이 불거진 가운데, 소속사와 영화 ‘호프’ 측이 사실관계를 반박하며 법적 대응에 나섰다. 29일 각종 온라인 커뮤니티와 SNS에는 황정민의 사생활을 둘러싼 의혹이 담긴 게시물이 올라왔다. 최초 게시자 A씨는 신설한 SNS 계정을 통해 자신이 황정민과 연인 관계였다고 주장하며 메신저 대화 캡처 이미지를 공개했다. 해당 게시물에는 문자 외에도 “네 카톡이 너무 귀여워서 전화한 거다”, “안아보고 싶다”고 말하는 황정민 추정 음성과 황정민의 사진 등이 담겼다. A씨는 황정민이 지속적으로 연락을 이어왔으며 촬영 중에도 만남을 제안했다고 폭로했다. 이에 황정민 측은 즉각 반박했다. 소속사 샘컴퍼니는 A씨가 “황정민을 지속적으로 괴롭힌 스토킹 범죄 피의자”라며 법원이 A씨의 스토킹 혐의를 인정해 세 차례 접근금지 등 잠정조치와 함께 벌금 300만원의 약식명령을 내렸다고 밝혔다. 아울러 “악의적으로 편집된 게시물에 대해 추가 법적 조치를 할 예정”이라고 경고했다.",
