      "title": "남궁민 맞아?…사투의 흔적 안고 길바닥에 주저 앉았다 ('결혼의완성')",
      "summary": "남궁민의 처참한 만신창이 몰골이 포착됐다. 지난 26일 방송된 KBS2 토일 미니시리즈 ‘결혼의 완성’ 8회는 전국 기준 7.3%를 기록하며 자체 최고 시청률을 경신했다. 지난 방송에서는 강태주(남궁민 분)가 아내 고세윤(이설 분)의 납치 사건과 관련된 듯한 장인 고동찬(장광 분)의 비밀을 추적하던 중 납치범 김경애(이상희 분)를 살해하려던 하정수(전광진 분)의 싸늘한 시신을 마주했다. 9회에서는 남궁민이 극한의 상황에 직면한 듯한 모습이 포착돼 긴장감을 자아낸다. 공개된 사진 속에는 강태주가 누군가의 전화를 받은 후 그대로 얼음처럼 굳어버린 모습이 담겼다. 이후 강태주가 온몸에 사투의 흔적이 고스란히 남은 모습으로 어두운 골목길 바닥에 주저앉아있다. 강태주가 골목에서 상처투성이가 된 채 망연자실 앉아 있는 이유는 무엇일지 이목이 쏠린다. 제작진 측은 “9회는 강태주가 본격적으로 판도라의 상자를 열어버리는 격렬한 과정이 펼쳐질 것”이라며 “강태주가 아내 고세윤 납치 사건의 진실을 제",
