      "title": "염승이, 강미나와 티격태격 자매 케미..“매 순간 즐거웠다” 종영 소감 (‘내일도 출근!’)",
      "summary": "배우 염승이가 드라마 ‘내일도 출근!’ 종영 소감을 밝혔다. 지난 28일 종영한 tvN 월화드라마 '내일도 출근!'은 N년차 직장인의 현실적인 연애와 일상을 그린 공감 멜로 작품이다. 염승이는 극 중 주인공 노아(강미나 분)의 언니이자 웹소설 작가인 다라 역을 맡아 열연을 펼쳤다. 극 중 다라는 회사를 그만두고 웹소설 작가로 전향해 프리랜서로 살아가는 인물이다. 다라는 운동복 차림에 털털한 모습으로 거실 한 편에 앉아 노트북으로 글을 쓰며, 동생 노아와 티격태격하는 한편 서로의 아픔을 깊이 이해하고 보듬어주는 찐자매 케미를 선보였다. 염승이는 동생 노아를 중심으로 일어나는 사건 속에서 섬세한 감정선을 유연하게 소화하며 시청자들의 눈도장을 찍었다. 특히 &#52453;소 칼로리를 따지며 잔소리를 하다가도, 동생에게 무슨 일이 생기면 누구보다 먼저 알아채고 편이 되어주는 다라의 입체적인 모습을 안정적인 연기력으로 그려내며 극의 몰입도를 높인 것. 작품을 마친 염승이는 \"함께 울고 웃으며",
