      "summary": "배우 강훈과 장규리가 소속사가 제작에 참여한 작품의 주연으로 나선다. 배우 매니지먼트와 콘텐츠 제작을 함께하는 회사가 늘면서 소속 배우가 자사 제작 작품에 출연하는 사례도 이어지고 있다. 다음 달 3일 처음 방송되는 tvN '최애의 사원'은 강훈의 첫 로맨틱 코미디 메인 주연작이다. 강훈은 남자 주인공을 맡아 극을 이끈다. 작품 제작에는 강훈의 소속사 앤피오엔터테인먼트가 참여했다. 강훈은 2014년 데뷔한 뒤 여러 작품에서 필모그래피를 쌓았다. MBC '옷소매 붉은 끝동'에서 홍덕로 역을 맡아 인지도를 높였고, 해당 작품 역시 앤피오엔터테인먼트가 제작했다. 이후 SBS '런닝맨' 임대 멤버로 출연해 대중적 인지도를 넓혔으며 '나의 해리에게', '메스를 든 사냥꾼' 등에 출연했다. '최애의 사원'에서는 처음으로 정극의 중심을 맡는다. 오는 8월 29일 처음 방송되는 tvN '포핸즈'에는 나무엑터스 소속 송강과 장규리가 출연한다. 나무엑터스는 이 작품의 제작에 참여했다. 송강은 이준영과",
