      "summary": "배우 박지현이 ‘내일도 출근!’을 통해 공감과 설렘을 선사했다. 박지현은 지난 28일 종영한 tvN 월화드라마 ‘내일도 출근!’(극본 김경민, 연출 조은솔, 기획 스튜디오드래곤, 제작 스튜디오드래곤·크로스픽쳐스)에서 새움전자 DA사업무에 근무하는 ‘일잘러’ 차지윤 역으로 열연했다. 박지현은 매일 퇴근을 꿈꾸는 직장인 ‘차지윤’으로 분해 섬세한 표현력이 돋보이는 호연으로 현대인들의 공감대를 형성했다. 뜻대로 되지 않는 연애 앞에서 다시 사랑을 할 용기를 내는 순간과 일에 대한 열정을 되찾고 꿈을 펼치는 담대한 면모를 세밀한 감정선으로 담아내 서사를 차곡차곡 쌓아 올렸고, 졸혼을 결심할 정도로 관계가 틀어진 부모님의 사이를 중재하려는 모습은 회사에서와는 또 다르게 딸로서의 역할을 하는 캐릭터를 완성했다. 박지현은 일상 속 직장인의 희로애락, 사랑 앞에서의 설렘과 망설임, 가족을 향한 애틋한 마음까지 한 인물 안에 담긴 다양한 감정을 자연스럽게 오가며 차지윤이라는 캐릭터를 입체적으로 완성",
