      "summary": "배우 염승이가 드라마 '내일도 출근!'&#8203;을 성공적으로 마무리하며 작품을 향한 애정과 감사가 담긴 종영 소감을 전했다. '내일도 출근!'은 N년 차 직장인의 현실적인 사랑과 일상을 그려낸 공감 멜로 드라마다. 염승이는 극 중 주인공 노아(강미나 분)의 언니이자 웹소설 작가인 다라 역을 맡아 현실감 넘치는 연기를 선보이며 시청자들의 공감을 이끌었다. 다라는 회사를 떠난 뒤 웹소설 작가로 새롭게 인생을 시작한 프리랜서 캐릭터다. 편안한 운동복 차림으로 거실 한편에서 노트북을 두드리며 집필에 몰두하는 일상부터, 동생 노아와 현실 자매 같은 티격태격 케미를 보여주는 동시에 서로의 상처를 가장 깊이 이해하고 보듬어주는 든든한 언니의 모습까지 자연스럽게 그려냈다. 이번 작품에서 염승이는 노아를 중심으로 전개되는 다양한 사건 속에서 섬세한 감정 연기를 안정감 있게 표현했다. 연애의 상처로 힘들어하는 동생을 조용히 안아주는 장면은 따뜻한 위로와 깊은 울림을 전하며 시청자들의 공감을 자아냈",
