      "summary": "2026년 방송가에서 나오기 힘들거라던 23.1%라는 경이로운 시청률 기록을 세운 SBS 금토드라마 '김부장'이 화려하게 퇴장했다. 배우 소지섭의 활약 속에 올 한 해 최고 흥행작에 오른 '김부장'의 빈 자리를 채울 작품은 무엇일까. 일단 31일 MBC 새 드라마 '유부녀 킬러'의 배우 공효진이 등판한다. '김부장' 소지섭이 떠난 자리를 노리는 주인공이 과거 레전드 로맨틱 코미디 '주군의 태양'에서 환상의 호흡을 맞췄던 파트너 공효진이라는 점이 흥미롭다. 소지섭이 국정원 요원의 독보적인 무력으로 딸을 되찾는 사적 복수극으로 금토극 정상을 휩쓸었다면, 이번엔 공효진이 저격총을 들고 사적 복수 대행자로 바통을 이어받는다. 또 하나의 재미있는 평행이론은 바로 주인공의 '직함'이다. 소지섭이 딸을 구하기 위해 무력을 개방한 아빠 ‘김부장’이었다면, 공효진이 연기할 인물 역시 두루미전자 영업3팀 부장이자 비밀 저격수인 유보나, 이른바 '유부장'이다. 웹툰 원작의 '유부녀 킬러'는 공효진의 본",
