      "summary": "“한국에서도 이런 퀄리티의 액션, 세계관을 가진 작품이 있다는 걸 알았으면 해요.” 배우 이동욱이 디즈니플러스 시리즈 ‘킬러들의 쇼핑몰’ 시즌2(이하 ‘킬쇼2’)로 돌아왔다. 이동욱은 최근 일간스포츠와 인터뷰에서 “시즌1이 많은 사랑을 받은 덕에 시즌2를 할 수 있게 됐다”며 “개인적으로 좋아하는 작품, 캐릭터를 또 할 수 있어서 기쁘다”고 소감을 전했다. 지난 22일부터 순차 공개 중인 ‘킬쇼2’는 독한 인수인계를 마치고 쇼핑몰 머더헬프의 새로운 대표가 된 정지안(김혜준)이 살아 돌아온 삼촌과 함께 바빌론 글로벌 세력에 맞서 본격적인 반격을 펼치는 이야기를 그린다. “2년 만에 촬영이라 걱정은 됐어요. 원래 그런 성격이 아닌데 떨리더라고요. 근데 막상 현장에 가니 시즌1 스태프가 다 있는 거예요. 뭔가 익숙해지면서 전날의 긴장감이 없어졌죠. 어제 찍고 오늘 만난 것처럼 일상 이야기와 농담을 주고받으면서 긴장이 풀어졌어요.” 이동욱은 전편에 이어 정진만을 연기했다. 전직 바빌론 출신",
