      "summary": "배우 정가희가 '재벌X형사2'에 합류 소식을 전했다. 내달 7일 첫 방송되는 SBS '재벌X형사2'는 유쾌상쾌통쾌 도파민 터지는 사이다 수사극을 그린다. 앞선 시즌1 역시 최고 시청률 11%를 기록하는 등 큰 인기를 얻었던 바 있다. 정가희는 날카로운 통찰력과 뛰어난 실력을 갖춘 국과수 부검의 캐릭터로 분한다. 그는 앞선 시즌에서도 거침없는 매력과 냉철한 전문성을 선보이며 강렬한 존재감을 드러낸 바 있다. 이번 시즌2에서 윤지원은 강력1팀과 더욱 긴밀한 공조 체제를 구축한다. 특히 사건의 핵심 실마리를 찾아내는 브레인 역할을 수행하며 극 중 '사이다' 같은 전개를 이끌어낼 예정이다. 정가희는 그동안 여러 작품에서 탄탄한 연기력을 입증해 왔다. 드라마 '키스는 괜히 해서!'에서는 악역의 양면성을 설득력 있게 표현했으며, '신이랑 법률사무소'에서는 사연 있는 에피소드의 주인공을 맡아 굴곡진 감정선을 소화했다. 정가희가 출연하는 '재벌X형사2'는 최고 시청률 23.1%를 기록한 '김부장'",
