      "summary": "정규앨범 활동 및 월드투어 이후 활동 종료 예고 팬 위한 다양한 음악과 이벤트 분비 개인의 성장 이루고 다시 만날 순간 약속 [더팩트ㅣ최현정 기자] '일단은' 처음이자 마지막 정규앨범이다. 하지만 이것이 '완전히 마지막'이 되지 않을 길은 여럿 열어두었다. 소속사 DSP미디어는 지난 6일 \"그룹 카드(KARD)가 28일 발매하는 첫 정규앨범 'Where To Now? (Part.2) : NOWHERE(웨어 투 나우? (파트2) : 노웨어)'의 방송 무대와 이후 이어지는 월드투어 'NOW HERE(나우 히어)'를 끝으로 모든 활동을 중단한다\"고 밝힌 바 있다. 하지만 앨범 발매에 앞서 21일 서울 광진구 카페 오버더레인보우에서 <더팩트>와 만난 카드(BM 전소민 제이셉 전지우)는 이것이 '카드의 해체'를 의미하는 것이 아니라 '더 큰 도약과 성장을 위한 시간'일 뿐이며 언젠가 다시 카드로 뭉칠 것이라고 분명하게 말했다. 더군다나 이들은 만약 'Where To Now? (Part.2)",
