      "summary": "매년 치열한 경쟁이 이어지는 K팝 그룹 중 2024년 데뷔한 그룹들이 각자의 색깔을 확립해 가고 있다. 그 중 이름에 공통적으로 'ㅅㅇ'이 들어가는 투어스(TWS)의 신유, 엔시티 위시(NCT WISH)의 시온, 나우즈(NOWZ)의 시윤이 나란히 특별한 존재감을 키우고 있다. 신유, 시온, 시윤은 데뷔 초부터 뛰어난 비주얼로 주목받았지만, 활동을 거듭할수록 무대 위 실력까지 인정받으며 팀의 중심축으로 자리매김했다. 신유는 2024년 1월 투어스 미니 1집 'Sparkling Blue'로 데뷔해 팀 특유의 청량함을 담당하고 있는 중심축이다. 안정적인 퍼포먼스와 무대에서 자연스러운 표현력, 훤칠한 피지컬이 어우러지며 그룹의 정체성을 보여주는 핵심 멤버로 활약하고 있다. 시온은 같은 해 2월 엔시티 위시의 싱글 1집 'WISH'로 데뷔해 리더로서 팀을 이끌고 있다. 안정적인 라이브와 퍼포먼스와 더불어 무대 안팎에서 중심을 잡아주는 역할까지 하며 성장세를 보여주고 있다. 부드러운 비주얼과",
