      "summary": "KBS 유튜브 채널 ‘케백수 오리지널’의 신규 웹예능 ‘돈선태’가 첫 방송 전부터 자극적인 썸네일로 뭇매를 맞고 있다. 논란이 불거진 것은 29일 공개된 걸그룹 리센느 멤버 원이, 미나미 출연분의 선공개 영상이다. MC를 맡은 ‘충주맨’ 김선태가 게스트인 원이, 미나미를 만나 이야기를 나눴는데, 제작진은 선공개 영상 썸네일에 ‘뭐가 무섭노?’라는 문구를 올리고 ‘노’ 부분만 색상을 다르게 강조해 업로드했다. 해당 문구는 과거 원이가 방송 중 사용한 말투로 인해 불거졌던 ‘일베 연상 논란’을 직접적으로 겨냥한 표현으로 풀이된다. 이를 두고 일각에서는 제작진이 조회수를 위해 출연진의 지나간 부정 이슈를 끌어다 쓴 이른바 ‘어그로성 마케팅’이라는 지적이 즉각 제기됐다. 논란이 확산하자 제작진은 썸네일 문구를 ‘예쁘게 봐도’로 급히 수정했지만 비판 여론은 쉽게 가라앉지 않고 있다. 실제 선공개 영상에서 김선태는 원이의 해당 이슈를 직접 언급하기도 했다. 김선태가 원이를 향해 “‘무섭노’ 사",
