      "summary": "그룹 UN 출신 가수 겸 배우 최정원이 약 5년간 이어진 법적 분쟁을 마무리한 뒤 장문의 심경을 전했다. 최정원은 29일 자신의 SNS를 통해 “거진 5년이라는 시간 동안 캄캄하고 질척한 늪 속에서 허우적대는 듯했다”며 “상간남 소송도, 스토킹 사건도 겪으며 인간 이하의 소리까지 들었다. 처절하게 버텨온 긴 터널 같은 시간이었다”고 털어놨다. 이어 “이제는 정말 모든 일이 끝났다”며 “상간남 소송에서는 승소해 부정한 행위를 하지 않았음이 명확히 확인됐고, 스토킹 사건도 불기소 처분을 받아 오해가 풀렸다”고 밝혔다. 그러면서 “너무 지쳤다. 앞으로는 경건하고 겸손한 한 사람으로 살아가려 한다”며 “사건이 터질 때는 사실이 아닌 이야기들도 산불처럼 번져 나가지만 정작 결말에는 관심을 갖지 않는 분들이 대부분인 것 같다”고 아쉬움을 드러냈다. 또 “가십으로 소비했던 분들이든, 진심으로 걱정해주셨던 분들이든 다시 한번 말씀드린다”며 “지난 5년간의 모든 일이 마무리됐음을 전하고 싶었다”고",
