      "summary": "그룹 몬스타엑스(MONSTA X)와 피프티피프티(FIFTY FIFTY)가 2026 아이치·나고야 아시안게임 MMA 국가대표 출정식 무대에 오른다. 로드FC는 오는 8월 29일 서울 장충체육관에서 열리는 ‘굽네 ROAD FC 078’을 2026 아이치·나고야 아시안게임 MMA 국가대표 출정식과 함께 개최한다고 밝혔다. 이번 행사는 아시안게임 정식 종목으로 채택된 MMA의 의미를 되새기고 국가대표 선수단의 선전을 기원하기 위해 마련됐다. 이날 대회에는 몬스타엑스(MONSTA X)와 피프티피프티(FIFTY FIFTY)가 공연을 펼친다. 로드FC는 MMA 경기와 K-POP 공연을 결합한 형태로 행사를 구성해 스포츠와 문화 콘텐츠를 함께 선보일 예정이다. 로드FC는 중국 베이징과 상하이, 창사, 일본 도쿄 등 해외 주요 도시에서 대회를 개최해 왔으며, 현재는 중국과 필리핀 현지 법인을 운영하며 해외 시장 확대를 이어가고 있다. 이번 프로젝트를 계기로 글로벌 콘텐츠 사업도 추진한다는 계획이다.",
