      "summary": "아이돌이 쌀 포대를 들자, 농협이 밥차를 보냈다. 여성 그룹 멤버가 “거제 야호”를 외치니 지방자치단체와 행정안전부가 줄줄이 손을 내밀었다. 광고 모델을 먼저 정하고 메시지를 입히던 공공 홍보의 순서가 뒤집혔다. 밈(Meme)으로 대변되는 아이돌 생태계를 ‘정책 바이럴’로 활용하는 기관들이 늘고 있다. 아일릿은 최근 메가 히트를 기록한 노래 ‘잇츠 미’(It’s Me)의 ‘미’를 쌀 미(米)로 바꾼 자체 광고를 선보여 짭짤한 재미를 봤다. 이런 아일릿의 재치에 농협은 음악 방송에 일명 ‘밥차’를 보내 호응했는가하면, 아일릿을 1호 ‘쌀 소비 촉진 홍보대사’로도 위촉해 인연을 이어갔다. 여성 그룹 리센느는 도시를 움직였다. 경남 거제 출신 원이의 유튜브 콘텐츠에서 나온 “거제 야호”가 짧은 영상을 타고 유행어가 퍼지자, 거제시는 리센느를 곧장 홍보대사로 위촉했다. 반향은 거제에 그치지 않았다. 다른 멤버들의 고향인 수원, 경주, 경기도 고양도 잇달아 리센느에게 홍보대사를 맡겼고, 급기",
