      "summary": "“다시 만나”자며 다음을 약속했던 더윈드가 1년 2개월 만에 한층 성장한 모습으로 돌아왔다. 청량이 가장 빛나는 계절, ‘청량 힙’이라는 새로운 색을 입은 더윈드가 다시 힘차게 달린다. 더윈드는 29일 오후 서울 강남구 일지아트홀에서 네 번째 미니앨범 ‘세컨드 윈드 : S#00’ 발매 쇼케이스를 열었다. ‘세컨드 윈드 : S#00’은 지친 순간 다시 찾아오는 힘, 그리고 더 높이 도약하기 위한 새로운 호흡을 담아낸 앨범이다. 이번 앨범을 기점으로 더윈드의 새로운 이야기도 본격적으로 펼쳐진다. 장현준은 “두 번째 바람이라는 앨범명처럼 이번 활동을 두 번째 기회라고 생각한다”며 “그동안 많이 성장했다는 것을 보여드리고 싶다”고 밝혔다. 이어 “실력도 향상됐지만 무엇보다 자신감이 많이 생겼다. 무대 위 표정과 제스처도 이전보다 다양해진 만큼 그런 변화를 눈여겨봐 주셨으면 좋겠다”고 말했다. 타이틀곡 ‘파티 라이크 어 록 스타’는 펑키한 메인 기타 리프와 EDM 스타일의 리드 신스가 조화를",
