      "summary": "프랑스 일렉트로팝의 전설로 불린 DJ 카빈스키(본명 뱅상 벨로르게이)가 세상을 떠났다. 향년 50세. 29일(현지시각) 영국 매체 메트로에 따르면 카빈스키는 이날 파리 자택에서 숨진 채 발견됐다. 파리 검찰은 \"사망 경위를 규명하기 위한 조사가 개시됐다\"고 밝혔다. 현장에 출동한 구급대는 수상한 정황을 발견하지 못한 것으로 전해졌다. 카빈스키는 2000년대 여러 EP를 발표하며 주목받았고, 2013년 첫 정규 앨범 '아웃런(OutRun)'을 내놨다. 특히 라이언 고슬링 주연 영화 '드라이브'에 삽입된 '나이트콜'이 세계적 인기를 얻으며 이름을 알렸다. 2024년 파리올림픽 폐회식에서는 벨기에 가수 앙젤과 함께 이 곡을 선보이기도 했다. '나이트콜'의 성공 이후 카빈스키는 9년의 공백기를 가졌고, 2022년 두 번째 앨범 '리본(Reborn)'으로 복귀했다. 카빈스키는 이에 대해 믹스맥과의 인터뷰에서 \"(첫 앨범의 성공에) 약간의 부담을 느꼈다\"며 \"사람들이 '나이트콜' 외에 다른 것",
