      "summary": "14살 소녀 셀레스트 리바스를 살해한 혐의로 기소된 미국 가수 D4vd(본명 데이비드 버크·21)의 재판에서 충격적인 악취에 관한 증언이 나왔다. 28일(현지시간) 연예 매체 TMZ에 따르면, 로스앤젤레스 카운티 검시관실의 그랜트 호 박사는 판사에게 10대 소녀의 시신에서 나는 악취가 너무 심해 부검실로 옮겨지기 전부터 복도에 진동할 정도였다고 증언했다. 이러한 악취 증언이 더욱 주목받는 이유는 시신 발견 당시의 정황 때문이다. 지난해 9월 할리우드의 한 견인차 보관소에서 악취를 이상하게 여긴 이들에 의해 끔찍하게 훼손된 시신이 발견되었고, 검찰은 당시 시신이 있던 테슬라 차량 내부에서 총 11개의 방향제가 발견되었다고 밝혔다. D4vd는 특별 가중 처벌이 적용되는 살인 혐의로 기소되어 사형 선고까지 가능한 상황이지만, 검찰은 아직 구형 여부를 결정하지 않았다. 그는 살인 외에도 14살 미만 아동에 대한 지속적인 성학대 및 시신 불법 훼손 혐의를 받고 있으나, 현재 무죄를 주장하고",
